WITH unpacked AS (SELECT id, plan, effective_from, ARRAY_MIN(tier_prices) AS lowest_price, AGGREGATE(tier_prices, 0.0D, (acc, p) -> acc + p, acc -> ROUND(acc / SIZE(tier_prices), 2)) AS avg_tier_price FROM price_tiers) SELECT DATE_TRUNC('MONTH', effective_from) AS activity_month, SUM(CASE WHEN plan = 'pro' THEN lowest_price ELSE 0 END) AS pro_lowest_price, SUM(CASE WHEN plan = 'starter' THEN avg_tier_price ELSE 0 END) AS starter_avg_tier_price FROM unpacked GROUP BY 1 HAVING pro_lowest_price < 0 ORDER BY pro_lowest_price ASC;
